@Test
public void testWindowScoedBean() {
    Assert.assertNotNull(windowContext);
    Assert.assertNotNull(someWindowScopedBean);
    {
        windowContext.activateWindow("window1");
        someWindowScopedBean.setValue("Hans");
        Assert.assertEquals("Hans", someWindowScopedBean.getValue());
    }
    // now we switch it away to another 'window'
    {
        windowContext.activateWindow("window2");
        Assert.assertNull(someWindowScopedBean.getValue());
        someWindowScopedBean.setValue("Karl");
        Assert.assertEquals("Karl", someWindowScopedBean.getValue());
    }
    // and now back to the first window
    {
        windowContext.activateWindow("window1");
        // which must still contain the old value
        Assert.assertEquals("Hans", someWindowScopedBean.getValue());
    }
    // and again back to the second window
    {
        windowContext.activateWindow("window2");
        // which must still contain the old value of the 2nd window
        Assert.assertEquals("Karl", someWindowScopedBean.getValue());
    }
}

@Test
public void permits() {
    {
        // failling case now
        final AtomicReference<Exception> failed = new AtomicReference<Exception>();
        final CountDownLatch latch = new CountDownLatch(2);
        final Thread[] concurrents = new Thread[] { new Thread() {

            @Override
            public void run() {
                service2.heavy(new Runnable() {

                    @Override
                    public void run() {
                        latch.countDown();
                    }
                });
            }
        }, new Thread() {

            @Override
            public void run() {
                try {
                    latch.await();
                } catch (final InterruptedException e) {
                    Thread.interrupted();
                    fail();
                }
                try {
                    service2.call("failed");
                    fail();
                } catch (final IllegalStateException ise) {
                    failed.set(ise);
                }
            }
        } };
        for (final Thread t : concurrents) {
            t.start();
        }
        latch.countDown();
        waitForThreads(concurrents);
        assertNotNull(failed.get());
        assertThat(failed.get(), instanceOf(IllegalStateException.class));
    }
    {
        // passing
        final CountDownLatch latch = new CountDownLatch(1);
        final Thread[] concurrents = new Thread[] { new Thread() {

            @Override
            public void run() {
                try {
                    latch.await();
                } catch (final InterruptedException e) {
                    Thread.interrupted();
                    fail();
                }
                service2.call("1");
            }
        }, new Thread() {

            @Override
            public void run() {
                try {
                    latch.await();
                } catch (final InterruptedException e) {
                    Thread.interrupted();
                    fail();
                }
                service2.call("2");
            }
        } };
        for (final Thread t : concurrents) {
            t.start();
        }
        latch.countDown();
        waitForThreads(concurrents);
        assertEquals(new HashSet<String>(asList("1", "2")), new HashSet<String>(service2.getCalled()));
    }
}

